  "Cents": {
    "type": "integer",
    "minimum": 0,
    "maximum": 100000000,
    "description": "Non-negative USD cents. Max $1,000,000.00."
  },
  "PositiveCents": {
    "type": "integer",
    "minimum": 1,
    "maximum": 100000000,
    "description": "Positive USD cents. Max $1,000,000.00."
  },
  "SignedCents": {
    "type": "integer",
    "description": "USD cents; may be negative (e.g. overspent remaining)."
  },
  "Version": {
    "type": "integer",
    "minimum": 1,
    "description": "Row version; starts at 1 and increments on every update."
  },
  "Cursor": {
    "type": "string",
    "minLength": 1,
    "maxLength": 200,
    "pattern": "^[A-Za-z0-9_-]+$",
    "description": "Opaque base64url cursor."
  },
  "Email": {
    "type": "string",
    "format": "email",
    "maxLength": 254
  },
  "Token": {
    "type": "string",
    "minLength": 43,
    "maxLength": 64,
    "pattern": "^[A-Za-z0-9_-]+$",
    "description": "Opaque base64url token from an emailed link (taken from the URL fragment)."
  },
  "NewPassword": {
    "type": "string",
    "minLength": 12,
    "maxLength": 128,
    "description": "Policy in auth.md (length, breached-password check). Violations are VALIDATION_FAILED with issue codes."
  },
  "DisplayName": {
    "type": "string",
    "minLength": 1,
    "maxLength": 50
  },
  "Timezone": {
    "type": "string",
    "minLength": 1,
    "maxLength": 64,
    "description": "IANA zone name accepted by the server's Intl database, e.g. `America/Chicago`.",
    "examples": [
      "America/New_York"
    ]
  },
  "Role": {
    "type": "string",
    "enum": [
      "owner",
      "member"
    ]
  },
  "CategoryKind": {
    "type": "string",
    "enum": [
      "expense",
      "income"
    ]
  },
  "Direction": {
    "type": "string",
    "enum": [
      "outflow",
      "inflow"
    ],
    "description": "outflow = money spent; inflow = money received (income or refund)."
  },
  "MfaMethod": {
    "type": "string",
    "enum": [
      "totp",
      "passkey",
      "recovery_code"
    ]
  },
  "ErrorCode": {
    "type": "string",
    "description": "Stable machine-readable code. Registry and HTTP status in errors.md.",
    "enum": [
      "VALIDATION_FAILED",
      "INVITATION_INVALID",
      "TOKEN_INVALID",
      "UNAUTHENTICATED",
      "INVALID_CREDENTIALS",
      "MFA_REQUIRED",
      "MFA_FAILED",
      "CSRF_FAILED",
      "FORBIDDEN",
      "REAUTH_REQUIRED",
      "ACCOUNT_PENDING_DELETION",
      "NOT_FOUND",
      "VERSION_CONFLICT",
      "ALREADY_EXISTS",
      "CATEGORY_IN_USE",
      "OWNER_CANNOT_LEAVE",
      "OWNS_SHARED_BUDGET",
      "MFA_NOT_ENABLED",
      "PAYLOAD_TOO_LARGE",
      "UNSUPPORTED_MEDIA_TYPE",
      "SPLITS_DO_NOT_SUM",
      "CATEGORY_ARCHIVED",
      "IDEMPOTENCY_KEY_REUSED",
      "LIMIT_REACHED",
      "RATE_LIMITED",
      "INTERNAL",
      "UNAVAILABLE"
    ]
  },
  "FieldIssue": {
    "type": "string",
    "description": "Stable per-field issue code. Registry in errors.md.",
    "enum": [
      "required",
      "unknown_field",
      "invalid_type",
      "invalid_format",
      "invalid_value",
      "too_small",
      "too_big",
      "too_short",
      "too_long",
      "breached_password",
      "duplicate",
      "sum_mismatch",
      "archived",
      "already_member",
      "invitation_pending",
      "limit"
    ]
  },
  "FieldError": {
    "type": "object",
    "additionalProperties": false,
    "required": [
      "in",
      "field",
      "issue",
      "message"
    ],
    "properties": {
      "in": {
        "type": "string",
        "enum": [
          "body",
          "query",
          "path",
          "header"
        ]
      },
      "field": {
        "type": "string",
        "maxLength": 200,
        "description": "Dotted path within `in`, array indexes as numbers (`splits.1.amountCents`). Empty string = the whole location."
      },
      "issue": {
        "$ref": "#/$defs/FieldIssue"
      },
      "message": {
        "type": "string",
        "description": "Safe English fallback. Never echoes the submitted value."
      }
    }
  },
  "ErrorBody": {
    "type": "object",
    "additionalProperties": false,
    "required": [
      "code",
      "message",
      "requestId"
    ],
    "properties": {
      "code": {
        "$ref": "#/$defs/ErrorCode"
      },
      "message": {
        "type": "string",
        "description": "Safe, human-readable fallback. Clients map `code` to their own copy."
      },
      "requestId": {
        "$ref": "#/$defs/RequestId"
      },
      "details": {
        "type": "array",
        "maxItems": 50,
        "description": "Present for VALIDATION_FAILED (always, at least one item) and optionally for 409/422 domain codes.",
        "items": {
          "$ref": "#/$defs/FieldError"
        }
      }
    }
  },
  "Health": {
    "type": "object",
    "additionalProperties": false,
    "required": [
      "status",
      "version"
    ],
    "properties": {
      "status": {
        "type": "string",
        "enum": [
          "ok"
        ]
      },
      "version": {
        "type": "string",
        "description": "Build git SHA (public repo, so not secret)"
      }
    }
  },
  "Readiness": {
    "type": "object",
    "additionalProperties": false,
    "required": [
      "status",
      "checks"
    ],
    "properties": {
      "status": {
        "type": "string",
        "enum": [
          "ok"
        ]
      },
      "checks": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "database"
        ],
        "properties": {
          "database": {
            "type": "string",
            "enum": [
              "ok"
            ]
          }
        }
      }
    }
  },
